class EventBus {
  constructor() {
    this.listeners = {};
  }

  listenerCount(event) {
    return this.listeners[event] ? this.listeners[event].length : 0;
  }

  on(event, fn) {
    if (!this.listeners[event]) {
      this.listeners[event] = [];
    }
    this.listeners[event].push(fn);
  }

  emit(event, ...args) {
    if (this.listeners[event]) {
      let error = null;
      this.listeners[event].forEach(fn => {
        try {
          fn(...args);
        } catch (e) {
          if (!error) {
            error = e;
          }
        }
      });
      if (error) {
        throw error;
      }
      return this.listeners[event].length;
    }
    return 0;
  }

  off(event, fn) {
