class Bank {
    constructor() {
        this.accounts = {};
    }

    open(name) {
        if (this.accounts[name]) {
            throw new Error('Account already exists');
        }
        this.accounts[name] = 0;
    }

    deposit(name, amount) {
        if (!this.accounts[name]) {
            throw new Error('Account does not exist');
