  const tokens = [];
  let i = 0;
  const n = expr.length;

  while (i < n) {
    const char = expr[i];

    if (/\d/.test(char) || (char === '.' && i + 1 < n && /\d/.test(expr[i + 1]))) {
      let num = '';
      while (i < n && (/\d/.test(expr[i]) || expr[i] === '.')) {
        num += expr[i];
