import re
from collections import Counter

def word_count(text):
    words = re.findall(r"\b[\w']+\b", text.lower())
    return Counter(words)

def top_words(text, n):
    word_counts = word_count(text)
    return word_counts.most_common(n)

# Example usage
if __name__ == "__main__":
