  });

  it('should tokenize an expression with a decimal number and a decimal number', function() {
    assert.deepStrictEqual(tokenize('1.5 + 2.5'), [{ type: 'number', value: 1.5 }, { type: 'operator', value: '+' }, { type: 'number', value: 2.5 }]);
